export class Releases {
  /**
   * List releases
   *
   * Returns a cursor-paginated page of releases for the current organization.
   */
  public static listReleases<ThrowOnError extends boolean = false>(
    options?: Options<ListReleasesData, ThrowOnError>,
  ): RequestResult<ListReleasesResponses, ListReleasesErrors, ThrowOnError> {
    return (options?.client ?? client).get<ListReleasesResponses, ListReleasesErrors, ThrowOnError>(
      {
        security: [{ scheme: "bearer", type: "http" }],
        url: "/releases",
        ...options,
      },
    );
  }

  /**
   * Create a new release
   *
   * Create a new release with the provided details and link the requested components. A release is immutable: there is no update endpoint, and the component list cannot change afterwards. Correcting one means deleting it and creating a new one, which starts a new deployment history.
   */
  public static createRelease<ThrowOnError extends boolean = false>(
    options: Options<CreateReleaseData, ThrowOnError>,
  ): RequestResult<CreateReleaseResponses, CreateReleaseErrors, ThrowOnError> {
    return (options.client ?? client).post<
      CreateReleaseResponses,
      CreateReleaseErrors,
      ThrowOnError
    >({
      security: [{ scheme: "bearer", type: "http" }],
      url: "/releases",
      ...options,
      headers: {
        "Content-Type": "application/json",
        ...options.headers,
      },
    });
  }

  /**
   * Delete a release
   *
   * Delete a release by their slug. Since a release is immutable, this plus a fresh create is the only way to change one -- and it discards the deployment history recorded against the old release. A release still deployed to a zone cannot be deleted (409).
   */
  public static deleteRelease<ThrowOnError extends boolean = false>(
    options: Options<DeleteReleaseData, ThrowOnError>,
  ): RequestResult<DeleteReleaseResponses, DeleteReleaseErrors, ThrowOnError> {
    return (options.client ?? client).delete<
      DeleteReleaseResponses,
      DeleteReleaseErrors,
      ThrowOnError
    >({
      security: [{ scheme: "bearer", type: "http" }],
      url: "/releases/{releaseSlug}",
      ...options,
    });
  }
}

